testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarProcessadorDePagamento } from './solution.mjs';

test('com dependências reais: calcula a taxa e notifica', () => {
  const notificacoes = [];
  const processador = criarProcessadorDePagamento({
    calcularTaxa: (total) => total * 0.1, // 10% de taxa
    notificar: (mensagem) => notificacoes.push(mensagem),
  });
  const resultado = processador.processar({ total: 100 });
  assert.deepEqual(resultado, { total: 100, taxa: 10, valorFinal: 110, status: 'aprovado' });
  assert.deepEqual(notificacoes, ['Pagamento de R$ 110.00 aprovado']);
});

test('trocar as dependências muda o comportamento (testabilidade)', () => {
  const processador = criarProcessadorDePagamento({
    calcularTaxa: () => 5, // taxa fixa
    notificar: () => {},  // fake que não faz nada
  });
  const resultado = processador.processar({ total: 100 });
  assert.equal(resultado.valorFinal, 105);
});

test('a construção exige as duas dependências como funções', () => {
  const completo = criarProcessadorDePagamento({ calcularTaxa: () => 0, notificar: () => {} });
  assert.equal(typeof completo.processar, 'function'); // com as duas, funciona
  assert.throws(() => criarProcessadorDePagamento({ notificar: () => {} }));
  assert.throws(() => criarProcessadorDePagamento({ calcularTaxa: () => 1 }));
  assert.throws(() => criarProcessadorDePagamento({ calcularTaxa: 'não função', notificar: () => {} }));
});

test('pedido inválido é recusado sem notificar ninguém', () => {
  const notificacoes = [];
  const processador = criarProcessadorDePagamento({
    calcularTaxa: () => 0,
    notificar: (mensagem) => notificacoes.push(mensagem),
  });
  assert.throws(() => processador.processar({ total: -5 }));
  assert.throws(() => processador.processar({}));
  assert.equal(notificacoes.length, 0);
});

solutionCode:
// INJEÇÃO DE DEPENDÊNCIAS: o processador RECEBE as dependências prontas em vez
// de criá-las por dentro — quem testa troca por fakes sem tocar no código real.
export function criarProcessadorDePagamento(dependencias) {
  if (typeof dependencias?.calcularTaxa !== 'function') {
    throw new Error('dependência calcularTaxa precisa ser uma função');
  }
  if (typeof dependencias?.notificar !== 'function') {
    throw new Error('dependência notificar precisa ser uma função');
  }

  return {
    processar(pedido) {
      if (typeof pedido?.total !== 'number' || pedido.total < 0) {
        throw new Error('pedido precisa ter total numérico maior ou igual a 0');
      }

      // O processador não sabe COMO a taxa é calculada nem COMO a notificação
      // sai: isso é responsabilidade das dependências que recebeu.
      const taxa = dependencias.calcularTaxa(pedido.total);
      const valorFinal = pedido.total + taxa;
      dependencias.notificar(`Pagamento de R$ ${valorFinal.toFixed(2)} aprovado`);

      return { total: pedido.total, taxa, valorFinal, status: 'aprovado' };
    },
  };
}
